import{_ as t,o as a,c as o,a0 as n}from"./chunks/framework.BTg7EidG.js";const r="/athanor-docs/screens/encounter.png",s="/athanor-docs/screens/tactical.png",m=JSON.parse('{"title":"Battles & Dungeons","description":"","frontmatter":{},"headers":[],"relativePath":"guide/combat.md","filePath":"guide/combat.md"}'),i={name:"guide/combat.md"};function l(h,e,d,c,g,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="battles-dungeons" tabindex="-1">Battles &amp; Dungeons <a class="header-anchor" href="#battles-dungeons" aria-label="Permalink to &quot;Battles &amp; Dungeons&quot;">​</a></h1><h2 id="joining-battle" tabindex="-1">Joining battle <a class="header-anchor" href="#joining-battle" aria-label="Permalink to &quot;Joining battle&quot;">​</a></h2><p><img src="'+r+'" alt="An encounter"></p><p>March onto an enemy and the game pauses to ask how you want to fight: <strong>Auto-resolve</strong> for a quick outcome, or <strong>⚔ Fight</strong> to take the tactical field yourself. You can also <strong>Fall back</strong> — unless you&#39;ve been ambushed.</p><p>Every engagement begins one of three ways. Ambushes either way are rare (a few percent, swayed by level difference — and rogue lords with the Ambush skill spring them more often):</p><ul><li><strong>Sprung ambush</strong> — you catch them unaware. On the field they stand asleep and take no turns until first struck.</li><li><strong>Battle</strong> — the sides face off and act in turns.</li><li><strong>Ambushed!</strong> — the enemy surrounds your party mid-field, and there is no declining the fight.</li></ul><h2 id="the-tactical-field" tabindex="-1">The tactical field <a class="header-anchor" href="#the-tactical-field" aria-label="Permalink to &quot;The tactical field&quot;">​</a></h2><p><img src="'+s+'" alt="A tactical battle"></p><p>Turns run by unit speed; each unit gets <strong>one move and one action</strong>. Blue tiles show where you can step — tap one to preview the move (and the red reach it would give you), then confirm. Red tiles show your weapon&#39;s reach: adjacent for melee, three tiles for shooters. Heroes with <em>Transmute Blast</em> get a cast mode that burns half their Essence on one target. <em>Rally</em>, <em>Shield Wall</em> and <em>Overwhelm</em> all apply on the field, and <strong>Withdraw</strong> breaks off the fight.</p><h2 id="dungeon-floors" tabindex="-1">Dungeon floors <a class="header-anchor" href="#dungeon-floors" aria-label="Permalink to &quot;Dungeon floors&quot;">​</a></h2><p>Garrisoned buildings fight <strong>floor by floor</strong> — the defenders split across the building&#39;s floors, and the <strong>STAIR DOWN</strong> hatch is visible on the far side of every hall. Clear the floor and the stair lights up: descend and fight on. With a <strong>rogue hero</strong> you have two more options:</p><ul><li><strong>Sneak past</strong> the next floor at the door — 25–75% by level. Fail, and that floor falls on you as an ambush.</li><li><strong>Flee down mid-fight</strong> — the whole party runs for the stair, eating parting blows based on how close the enemies stand and how fast each runner is. Slow units can die on the stairs.</li></ul><h2 id="the-prize-at-the-bottom" tabindex="-1">The prize at the bottom <a class="header-anchor" href="#the-prize-at-the-bottom" aria-label="Permalink to &quot;The prize at the bottom&quot;">​</a></h2><p>Every stormed hold ends in a prize: a <strong>chest</strong> of coin and stores scaled by how deep you fought, an <strong>artifact</strong> — finer the closer to the world&#39;s blighted heart — or, rarely, a <strong>caged hero</strong> who joins their rescuer. Victors also strip the fallen of their gear, and beaten marauder garrisons often guarded a hoard.</p>',14)])])}const p=t(i,[["render",l]]);export{m as __pageData,p as default};
